import{describe,it,expect}from"vitest";import{MONSOON_DATA,getMonsoonModeData,getPhaseDetails,calculateWindPathDashOffset,validateScientificData}from"../../frontend/monsoon-explainer/monsoon-explainer.js";describe("Monsoon Explainer Dataset Integrity",()=>{it("contains both Southwest (SW) and Northeast (NE) monsoon systems",()=>{expect(MONSOON_DATA).toHaveProperty("sw"),expect(MONSOON_DATA).toHaveProperty("ne")}),it("validates dataset structure according to IMD meteorological standards",()=>{const e=validateScientificData(MONSOON_DATA);expect(e.isValid).toBe(!0),expect(e.errors).toEqual([])}),it("every mode contains at least 4 distinct phase progression steps",()=>{["sw","ne"].forEach(e=>{const t=MONSOON_DATA[e];expect(Array.isArray(t.phases)).toBe(!0),expect(t.phases.length).toBeGreaterThanOrEqual(4),t.phases.forEach((e,t)=>{expect(e).toHaveProperty("step"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("period"),expect(e).toHaveProperty("desc"),expect(e.step).toBe(t+1),expect(e.title.trim().length).toBeGreaterThan(0),expect(e.desc.trim().length).toBeGreaterThan(0)})})}),it("contains primary air mass branches for both systems",()=>{expect(MONSOON_DATA.sw.branches.length).toBe(2),expect(MONSOON_DATA.ne.branches.length).toBe(2),expect(MONSOON_DATA.sw.branches[0].name).toContain("Arabian Sea"),expect(MONSOON_DATA.sw.branches[1].name).toContain("Bay of Bengal")})}),describe("Mode Switching Logic",()=>{it("retrieves Southwest monsoon data for sw mode",()=>{const e=getMonsoonModeData("sw");expect(e.id).toBe("sw"),expect(e.title).toContain("Southwest")}),it("retrieves Northeast monsoon data for ne mode",()=>{const e=getMonsoonModeData("ne");expect(e.id).toBe("ne"),expect(e.title).toContain("Northeast")}),it("handles uppercase and whitespace input gracefully",()=>{const e=getMonsoonModeData(" NE ");expect(e.id).toBe("ne")}),it("defaults to SW monsoon data for invalid or missing mode key",()=>{const e=getMonsoonModeData("invalid_mode");expect(e.id).toBe("sw")})}),describe("Phase Step Lookup",()=>{it("retrieves correct phase details by 1-based index",()=>{const e=getPhaseDetails("sw",1);expect(e.step).toBe(1),expect(e.title).toContain("Phase 1");const t=getPhaseDetails("ne",4);expect(t.step).toBe(4),expect(t.title).toContain("Phase 4")}),it("safely bounds out-of-range phase indices",()=>{const e=getPhaseDetails("sw",10);expect(e.step).toBe(4);const t=getPhaseDetails("sw",0);expect(t.step).toBe(1)})}),describe("SVG Wind Path Dashoffset Math",()=>{it("calculates stroke-dashoffset 500 (fully hidden) at 0% progress",()=>{expect(calculateWindPathDashOffset(0,500)).toBe(500)}),it("calculates stroke-dashoffset 250 (half visible) at 50% progress",()=>{expect(calculateWindPathDashOffset(50,500)).toBe(250)}),it("calculates stroke-dashoffset 0 (fully visible path) at 100% progress",()=>{expect(calculateWindPathDashOffset(100,500)).toBe(0)}),it("safely bounds input percentage values between 0 and 100",()=>{expect(calculateWindPathDashOffset(150,500)).toBe(0),expect(calculateWindPathDashOffset(-20,500)).toBe(500)})});